import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { ArrowLeft, Camera, Scan, Recycle, AlertTriangle, Sparkles, UploadCloud, Trash2 } from 'lucide-react';

const wasteExamples = [
    { name: 'Plastic Bottles', src: 'data:image/jpeg;base64,' },
    { name: 'Styrofoam', src: 'data:image/jpeg;base64,' },
    { name: 'Tires', src: 'data:image/jpeg;base64,' },
    { name: 'Mixed Waste', src: 'data:image/jpeg;base64,' },
];

const ReflowVisionPage = () => {
    const [uploadedImage, setUploadedImage] = useState(null);
    const [result, setResult] = useState(null);
    const [isClassifying, setIsClassifying] = useState(false);

    const handleImageUpload = (e) => {
        const file = e.target.files[0];
        if (file) {
            setUploadedImage(URL.createObjectURL(file));
            setResult(null);
        }
    };

    const handleClassify = () => {
        if (!uploadedImage) return;
        setIsClassifying(true);
        setResult(null);
        setTimeout(() => {
            // Simulated classification logic
            const rand = Math.random();
            let classification;
            if (rand < 0.4) {
                classification = { type: 'Plastic Bottles', recyclable: true, hazardous: false, value: 0.8 };
            } else if (rand < 0.7) {
                classification = { type: 'Mixed Waste', recyclable: false, hazardous: false, value: 0.2 };
            } else {
                classification = { type: 'Hazardous Foam', recyclable: false, hazardous: true, value: 0 };
            }
            setResult(classification);
            setIsClassifying(false);
        }, 1500);
    };

    return (
        <div className="py-12 bg-background-grey">
            <div className="container mx-auto px-4">
                <Link to="/" className="inline-flex items-center text-primary font-semibold mb-8 hover:underline">
                    <ArrowLeft size={20} className="mr-2" />
                    Back to Home
                </Link>
                <div className="flex justify-between items-center mb-8">
                    <h1 className="text-3xl font-bold text-text-dark flex items-center"><Camera className="mr-3"/>ReFlow Vision Classifier</h1>
                </div>

                {/* Waste Examples */}
                <div className="mb-12">
                    <h2 className="text-2xl font-bold text-text-dark mb-4 text-center">Waste Type Examples</h2>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        {wasteExamples.map(ex => (
                            <div key={ex.name} className="text-center">
                                <img src={ex.src} alt={ex.name} className="w-full h-40 object-cover rounded-lg shadow-md" />
                                <p className="mt-2 font-semibold">{ex.name}</p>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="grid lg:grid-cols-2 gap-8">
                    <div className="bg-white p-8 rounded-xl shadow-md">
                        <h2 className="text-xl font-bold text-text-dark mb-4">1. Upload Waste Image</h2>
                        <div className="mt-1 flex justify-center px-6 pt-10 pb-10 border-2 border-border-color border-dashed rounded-md">
                            <div className="space-y-1 text-center">
                                {uploadedImage ? (
                                    <img src={uploadedImage} alt="Uploaded waste" className="mx-auto h-64 w-auto rounded-lg" />
                                ) : (
                                    <>
                                        <UploadCloud className="mx-auto h-12 w-12 text-gray-400" />
                                        <div className="flex text-sm text-gray-600">
                                            <label htmlFor="file-upload" className="relative cursor-pointer bg-white rounded-md font-medium text-primary hover:text-primary-hover focus-within:outline-none">
                                                <span>Upload a file</span>
                                                <input id="file-upload" name="file-upload" type="file" className="sr-only" accept="image/*" onChange={handleImageUpload} />
                                            </label>
                                            <p className="pl-1">or drag and drop</p>
                                        </div>
                                        <p className="text-xs text-gray-500">PNG, JPG up to 10MB</p>
                                    </>
                                )}
                            </div>
                        </div>
                        <button onClick={handleClassify} disabled={isClassifying || !uploadedImage} className="mt-6 w-full btn-primary flex items-center justify-center disabled:bg-gray-400 disabled:cursor-not-allowed">
                            {isClassifying ? <><Sparkles className="animate-spin mr-2"/> Classifying...</> : <><Scan className="mr-2"/> Classify Waste</>}
                        </button>
                    </div>

                    <div className="bg-white p-8 rounded-xl shadow-md">
                        <h2 className="text-xl font-bold text-text-dark mb-4">2. Classification Result</h2>
                        <div className="h-full flex items-center justify-center bg-background-grey rounded-lg p-8 text-center min-h-[300px]">
                            {!result && !isClassifying && <p className="text-text-light">Upload an image and click "Classify Waste".</p>}
                            {isClassifying && <p className="text-text-light">Analyzing image...</p>}
                            {result && (
                                <div className="space-y-4">
                                    {result.recyclable && <Recycle className="h-16 w-16 text-success mx-auto"/>}
                                    {result.hazardous && <AlertTriangle className="h-16 w-16 text-danger mx-auto"/>}
                                    {!result.recyclable && !result.hazardous && <Trash2 className="h-16 w-16 text-secondary mx-auto"/>}
                                    <h3 className="text-2xl font-bold text-text-dark">{result.type}</h3>
                                    <p className={`text-lg font-semibold ${result.recyclable ? 'text-success' : result.hazardous ? 'text-danger' : 'text-secondary'}`}>
                                        {result.recyclable ? 'Recyclable' : result.hazardous ? 'Hazardous' : 'Non-Recyclable'}
                                    </p>
                                    <p className="text-xl">Estimated Value: <span className="font-bold">${result.value.toFixed(2)}/kg</span></p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ReflowVisionPage;
